            category: 'field',
            field,
            id: changeId,
            objectId,
            objectKind,
            originalValue,
            ownerId: null,
            regionIndex: null,
            value,
        }
        this.setChange(change, ownerKey, Object.is(originalValue, value))
        this.commitTransaction([])
        const detail = { field, objectId, objectKind, previousValue, value }
